        if(runtime.snapshot()!=null){TrackingService.Snapshot snapshot=runtime.snapshot();if(snapshot!=null&&snapshot.phase.equals("DELAYED"))delayed(snapshot);else if(snapshot!=null&&snapshot.phase.equals("ARMED"))armed(snapshot);else{sawLive=true;live(snapshot);}}else{TrackingDelayRuntime.get(this).inspect(TrackingService::holdsDelayJournal,TrackingDndRuntime.boot(this));setup();}
