    private void rememberSetupPosition(){if(!rendered.equals("SETUP")||renderedSetupRoute.isEmpty())return;ScrollView scroll=setupScroll(getWindow().getDecorView());if(scroll!=null)setupPositions.put(renderedSetupRoute,scroll.getScrollY());}
    private void restoreSetupPosition(){ScrollView scroll=setupScroll(getWindow().getDecorView());String owner=setupRoute;if(scroll!=null){int position=setupPositions.getOrDefault(owner,0);scroll.post(()->{if(!isDestroyed()&&rendered.equals("SETUP")&&setupRoute.equals(owner))scroll.scrollTo(0,position);});}}
    private void setupPage(String route){if(startRequested)return;rememberSetupPosition();setupRoute=route;setup();}
    private void back(){if(liveOptions){closeLiveOptions();return;}if(rendered.equals("SETUP")&&!setupRoute.equals("setup")){setupPage(setupRoute.equals("power")?"more":"setup");return;}finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
