        if(!sonar){setupMenuRow(body,"clock","Automatic tracking","Review a schedule or stillness start","Set up",()->startActivityForResult(RecordUi.intent(this,AutomaticTrackingActivity.class),92));return;}
        LinearLayout mode=Design.row(this);mode.setMinimumHeight(Design.dp(this,48));mode.addView(Design.text(this,"Start manually",13,500,Design.CREAM),new LinearLayout.LayoutParams(0,-2,1));mode.addView(Design.text(this,"Contactless",13,400,Design.LILAC));body.addView(mode,new LinearLayout.LayoutParams(-1,-2));
