        setupMenuRow(body,"calendar","Nightly tracking schedule","Movement only · review saved days and times",null,()->startActivity(RecordUi.intent(this,RecurringTrackingActivity.class)));
        if(!sonar)setupMenuRow(body,"clock","Choose automatic start","Review or arm a bounded wait for tonight",null,()->startActivityForResult(RecordUi.intent(this,AutomaticTrackingActivity.class),92));
        heading(body,"Sensors & battery");
        setupMenuRow(body,"phone","Movement sensitivity","On-bed motion settings",motionLabel(),()->startActivity(RecordUi.intent(this,MotionSensorActivity.class)));
        setupMenuRow(body,"battery","Sampling & battery","Adaptive rates, sensor batching and battery reserve",reserveLabel(),()->setupPage("power"));
        if(sonar)setupMenuRow(body,"sonar","Breathing experiment settings","Optional contactless estimates",null,()->startActivity(RecordUi.intent(this,EchoSettingsActivity.class)));
        heading(body,"While recording");
        setupMenuRow(body,"phone","Flip to pause (movement only)","Review orientation pause and resume",null,()->startActivity(RecordUi.intent(this,TrackingFlipActivity.class)));
        setupMenuRow(body,"bell","Tracking Do Not Disturb","Optional notification policy",null,()->startActivity(RecordUi.intent(this,TrackingDndActivity.class)));
        setupMenuRow(body,"moon","Timed dream cues","Review cue timing and output choices",null,()->startActivity(RecordUi.intent(this,DreamCueActivity.class)));
        if(!sonar)setupMenuRow(body,"phone","Pair movement tracking","Optional second-phone movement input",null,()->startActivity(RecordUi.intent(this,PairMotionActivity.class)));
        Design.space(body,10);setupMenuError(body);action(footer(body),"Back to tracking setup",false,()->setupPage("setup"));
