    private void powerTrackingSettings(){
        LinearLayout body=Design.darkPage(this);Design.pad(body,24,8);setupHeader(body,"Sampling & battery",()->setupPage("more"));text(body,"Tracking setup · More settings",12,400,Design.LILAC);Design.space(body,16);
        Switch battery=toggle(body,"battery","Battery-aware sampling",!sonar&&batteryAware,on->{batteryAware=on;Prefs.of(this).edit().putBoolean(BatterySampling.KEY,on).apply();});battery.setEnabled(!sonar);battery.setAlpha(sonar?.45f:1f);
        text(body,sonar?"Available for phone movement and light recording.":"Use fewer sensor updates when your battery is low.",12,400,Design.LILAC);Design.space(body,10);line(body);
        setupMenuRow(body,"info","How battery sampling works",null,null,()->SleepPicker.message(this,"Battery-aware sampling","At 20% or less while unplugged, movement is requested every 0.5 seconds and light every second. Normal rates return when charging or at 25%. This lowers time resolution and applies to the next recording. Automatic waiting, alarm deadlines and contactless audio processing stay unchanged."));
        boolean batchWanted=false,batchInvalid=false;String batchSupport="";try{batchWanted=BatchedMotion.requested(this);}catch(RuntimeException invalid){batchInvalid=true;batchSupport="Saved batching setting needs review. Reset it Off before tracking.";}try{BatchedMotion.supported(this);}catch(RuntimeException unavailable){if(!batchInvalid)batchSupport=unavailable.getMessage()==null?"Sensor batching is unavailable":unavailable.getMessage();}
        heading(body,"Manual movement recording");
        Switch batchToggle=toggle(body,"battery","Sensor batching",batchWanted,on->{Prefs.of(this).edit().putBoolean(BatchedMotion.KEY,on).apply();setup();});batchToggle.setEnabled(batchSupport.isEmpty()||batchWanted);batchToggle.setAlpha(batchToggle.isEnabled()?1f:.45f);if(batchInvalid)action(body,"Reset sensor batching Off",false,()->{Prefs.of(this).edit().putBoolean(BatchedMotion.KEY,false).apply();setup();});
        text(body,batchSupport.isEmpty()?"Collect sensor updates together. Check compatibility before using.":batchSupport,12,400,Design.LILAC);Design.space(body,10);line(body);
        setupMenuRow(body,"info","Batching compatibility",null,null,()->SleepPicker.message(this,"Sensor batching","Requires a wake-up accelerometer with a hardware buffer. Requests 5 updates per second with delivery up to15seconds later. Sounds, light recording, flip pause, start delay and battery-aware sampling must be off. Paired movement and timed cues are not supported together with batching. Power savings depend on the phone."));
        action(body,"Battery reserve: "+reserveLabel(),false,this::chooseReserve);
        text(body,"Save your night and stop tracking at this battery level. Applies next recording or wait."+(sonar?" Contactless tracking still requires charging.":""),12,400,Design.LILAC);
        String reserveResult=Prefs.text(this,TrackingBatteryReserve.RESULT,"");if(!reserveResult.isEmpty())text(body,"Last reserve stop · "+reserveResult,12,500,Design.LILAC);Design.space(body,10);line(body);
        setupMenuError(body);action(footer(body),"Done",false,()->setupPage("more"));
    }
    private String reserveLabel(){try{int selected=TrackingBatteryReserve.requested(this);return selected==0?"Off":selected+"%";}catch(RuntimeException invalid){return "Needs review";}}
    private void chooseReserve(){
        String[] titles={"Off","5% battery","10% battery","15% battery","20% battery","30% battery"};int choice=0;try{int saved=TrackingBatteryReserve.requested(this);for(int n=0;n<TrackingBatteryReserve.OPTIONS.length;n++)if(TrackingBatteryReserve.OPTIONS[n]==saved)choice=n;}catch(RuntimeException invalid){showError(invalid.getMessage());}
        if(reserveDialog!=null)reserveDialog.dismiss();reserveDialog=SleepPicker.choices(this,"Stop tracking to reserve battery",titles,choice,n->{Prefs.of(this).edit().putInt(TrackingBatteryReserve.KEY,TrackingBatteryReserve.OPTIONS[n]).apply();showError("");setup();});
    }
    private void sensor(LinearLayout body,String icon,String title,String help,boolean selected,boolean movement){
        LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,80));Design.pad(row,14,10);GradientDrawable background=Design.shape(this,selected?0xff3a3046:Color.TRANSPARENT,16);background.setStroke(Design.dp(this,1),selected?Design.VIOLET:0xff51485e);row.setBackground(background);
        SleepPicker.Mark radio=new SleepPicker.Mark(this,selected,selected?Design.LILAC:0xff9786aa);row.addView(radio,new LinearLayout.LayoutParams(Design.dp(this,26),Design.dp(this,26)));
        Design.Icon glyph=new Design.Icon(this,icon,selected?Design.LILAC:0xff9786aa);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(this,32),Design.dp(this,32));ip.setMargins(Design.dp(this,8),0,Design.dp(this,14),0);row.addView(glyph,ip);LinearLayout words=Design.col(this);text(words,title,15,600,selected?Design.CREAM:Design.LILAC);Design.space(words,4);text(words,help,12,400,Design.LILAC);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));row.setSelected(selected);row.setContentDescription(title+(selected?" selected":""));row.setStateDescription(selected?"Selected":"Not selected");row.setFocusable(true);row.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
        row.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(RadioButton.class.getName());info.setCheckable(true);info.setChecked(selected);}});
        row.setOnClickListener(v->{if(movement){if(sonar){sonar=false;showError("");setup();}}else openSonar();});body.addView(row,new LinearLayout.LayoutParams(-1,-2));
    }
    private void openSonar(){startActivityForResult(RecordUi.intent(this,ContactlessSetupActivity.class),93);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==93&&result==RESULT_OK){try{SonarSettings.load(this);sonar=true;showError("");setup();}catch(RuntimeException invalid){showError(invalid.getMessage());}}}
    private String delayLabel(){try{return TrackingDelayActivity.label(new TrackingDelaySettings(TrackingDelaySettings.factory.open(this)).minutes());}catch(RuntimeException invalid){return "Needs review";}}
    private String motionLabel(){try{return MotionSettings.load(this).label();}catch(Exception e){return "Needs review";}}
    private Switch toggle(LinearLayout body,String icon,String title,boolean checked,java.util.function.Consumer<Boolean> change){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,48));Design.Icon glyph=new Design.Icon(this,icon,Design.CREAM);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(this,26),Design.dp(this,26));ip.rightMargin=Design.dp(this,18);row.addView(glyph,ip);row.addView(Design.text(this,title,15,500,Design.CREAM),new LinearLayout.LayoutParams(0,-2,1));Switch s=new Switch(this);Design.styleSwitch(this,s,Design.VIOLET,0xff655a71);s.setContentDescription(title);s.setChecked(checked);s.setOnCheckedChangeListener((v,on)->{change.accept(on);if(Appearance.reduced(this))s.jumpDrawablesToCurrentState();});row.addView(s);row.setOnClickListener(v->{if(s.isEnabled())s.performClick();});row.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);body.addView(row);return s;}
    private String sonarSoundHelp(){return !sonarAnalysis?"Analysis off · sonar still uses the microphone.":sonarClips?"This night only · estimates and optional ten-second sound clips.":"This night only · estimates; saving sound clips is off.";}
