    static Intent controlIntent(Activity owner,String action,TrackingService.Snapshot current,boolean visible){Intent intent=new Intent(owner,TrackingService.class).setAction(action);if(TrackingService.RESUME.equals(action)&&current!=null&&current.sonar){if(!visible)throw new IllegalStateException("Open tracking before resuming contactless capture.");SonarEntry.Ticket admission=SonarEntry.issue(true,SystemClock.elapsedRealtime(),current.id,new SonarConfig(current.sonarGain),current.soundsRequested,current.keepClips);intent.putExtra("sonarAdmission",admission.nonce);}return intent;}
