    private boolean liveUiCurrent(View owner){TrackingService.Snapshot current=runtime.snapshot();return owner==liveOwner&&owner.isAttachedToWindow()&&resumed&&hasWindowFocus()&&!isFinishing()&&!isDestroyed()&&current!=null&&current.id==liveSession&&!current.phase.equals("ARMED")&&!current.phase.equals("DELAYED");}
    private void rememberLiveOptionsPosition(){if(liveOptions&&liveOwner!=null&&liveOwner.isAttachedToWindow()&&liveOwner.getParent() instanceof ScrollView scroll)liveOptionsPosition=scroll.getScrollY();}
    private void openLiveOptions(View owner){if(!liveUiCurrent(owner))return;liveOptions=true;live(runtime.snapshot());}
    private void closeLiveOptions(){rememberLiveOptionsPosition();liveOptions=false;liveOwner=null;TrackingService.Snapshot current=runtime.snapshot();if(current!=null&&!current.phase.equals("ARMED")&&!current.phase.equals("DELAYED"))live(current);else refresh();}
