    // Move known informational labels only; unrecognised or fault statuses stay on the main page.
    private boolean reserveDetail(String value){return value==null||value.isEmpty()||Set.of("Battery reserve off","Battery reserve state unavailable").contains(value)||value.matches("Reserve [0-9]+% · battery [0-9]+% · (connected|stops tracking at threshold)");}
    private boolean samplingDetail(String value){if(value==null||value.isEmpty())return true;if(Set.of("Normal sampling","Normal sampling · battery-aware mode off","Normal sampling · battery state unavailable","Battery-aware sampling does not change contactless capture","Paused · movement/light capture stopped","Sensor batching paused","Sensor batching · preparing capture","Draining pending sensor readings…","Batch segment closed","Wake-up FIFO · 5 Hz requested · delivery up to 15 s").contains(value))return true;return value.matches("Normal sampling · [0-9]+%( · (charging|reduces at 20%))?")||value.matches("Battery-aware · [0-9]+% · motion 0[.]5 s / light 1 s requested");}
    private boolean flipDetail(String value){return value==null||value.isEmpty()||Set.of("Off","Unavailable with contactless tracking","Waiting for recording to start","Face up, then face down to pause","Finishing capture before the pause","Flip pause · face up or wait up to 5 min","Resuming this recording","Manual pause · automatic resume is off").contains(value);}
